export class TouchControls{
 constructor(onAction,onLook){
  this.enabled=matchMedia('(pointer:coarse)').matches;this.mx=this.mz=0;this.fire=false;this.aim=false;this.stance='stand';this.pointer=null;this.lookPointer=null;this.vehicleMode=false;this.drive={left:0,right:0,throttle:0,brake:0};document.body.classList.toggle('touch-device',this.enabled);const $=id=>document.getElementById(id);
  for(const[id,field]of[['drive-left','left'],['drive-right','right'],['drive-accelerate','throttle'],['drive-brake','brake']]){const button=$(id);let pointer=null;button.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();pointer=e.pointerId;this.drive[field]=1;button.classList.add('held');button.setPointerCapture(e.pointerId);});for(const event of['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,e=>{if(e.pointerId===pointer){pointer=null;this.drive[field]=0;button.classList.remove('held');}});}
  const driverLook=$('drive-look');let driverPointer=null,dx=0,dy=0;driverLook.addEventListener('pointerdown',e=>{e.preventDefault();driverPointer=e.pointerId;dx=e.clientX;dy=e.clientY;driverLook.setPointerCapture(e.pointerId);});driverLook.addEventListener('pointermove',e=>{if(e.pointerId===driverPointer){onLook(e.clientX-dx,e.clientY-dy);dx=e.clientX;dy=e.clientY;}});for(const event of['pointerup','pointercancel','lostpointercapture'])driverLook.addEventListener(event,e=>{if(e.pointerId===driverPointer)driverPointer=null;});
  $('drive-exit').onclick=()=>onAction('interact');
  if(!this.enabled)return;const stick=$('joystick'),knob=$('stick-knob'),zone=$('touch-look');
  const update=e=>{const b=stick.getBoundingClientRect(),x=(e.clientX-b.left-b.width/2)/42,y=(e.clientY-b.top-b.height/2)/42,n=Math.max(1,Math.hypot(x,y));this.mx=x/n;this.mz=-y/n;knob.style.transform=`translate(${this.mx*35}px,${-this.mz*35}px)`;};
  stick.addEventListener('pointerdown',e=>{e.preventDefault();if(this.pointer!==null)return;this.pointer=e.pointerId;stick.setPointerCapture(e.pointerId);update(e);});stick.addEventListener('pointermove',e=>{if(e.pointerId===this.pointer){e.preventDefault();update(e);}});const release=e=>{if(e.pointerId===this.pointer){this.pointer=null;this.mx=this.mz=0;knob.style.transform='';}};for(const event of['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(event,release);
  zone.addEventListener('pointerdown',e=>{e.preventDefault();if(this.lookPointer!==null)return;this.lookPointer=e.pointerId;this.lastX=e.clientX;this.lastY=e.clientY;zone.setPointerCapture(e.pointerId);});zone.addEventListener('pointermove',e=>{if(e.pointerId===this.lookPointer){e.preventDefault();onLook(e.clientX-this.lastX,e.clientY-this.lastY);this.lastX=e.clientX;this.lastY=e.clientY;}});for(const event of['pointerup','pointercancel','lostpointercapture'])zone.addEventListener(event,e=>{if(e.pointerId===this.lookPointer)this.lookPointer=null;});
  const fire=$('touch-fire');let fireId=null,fx=0,fy=0;fire.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();fireId=e.pointerId;fx=e.clientX;fy=e.clientY;this.fire=true;onAction('fire-start');fire.setPointerCapture(e.pointerId);fire.classList.add('held');});fire.addEventListener('pointermove',e=>{if(e.pointerId===fireId){e.preventDefault();const x=e.clientX-fx,y=e.clientY-fy,gain=.32+Math.min(1.6,Math.hypot(x,y)*.045);onLook(x*gain,y*gain);fx=e.clientX;fy=e.clientY;}});for(const event of['pointerup','pointercancel','lostpointercapture'])fire.addEventListener(event,e=>{if(e.pointerId===fireId){fireId=null;this.fire=false;fire.classList.remove('held');}});
  $('touch-aim').addEventListener('pointerdown',e=>{e.preventDefault();this.aim=!this.aim;onAction('combat');$('touch-aim').classList.toggle('held',this.aim);});$('touch-stance').addEventListener('pointerdown',e=>{e.preventDefault();this.stance={stand:'crouch',crouch:'prone',prone:'stand'}[this.stance];onAction('stance:'+this.stance);});
  for(const[id,action]of[['touch-jump','jump'],['touch-loot','context'],['touch-switch','switch'],['touch-view','view']])$(id).addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();onAction(action);});
  $('touch-kit').onclick=()=>{this.fire=false;$('touch-fire').classList.remove('held');$('kit-tray').hidden=!$('kit-tray').hidden;};for(const b of document.querySelectorAll('[data-kit]'))b.onclick=()=>{onAction(b.dataset.kit);$('kit-tray').hidden=true;};$('minimap').addEventListener('pointerdown',e=>{e.preventDefault();e.currentTarget.classList.toggle('expanded');});document.addEventListener('touchmove',e=>{if(document.body.classList.contains('playing')&&!e.target.closest('.modal,dialog,.inventory'))e.preventDefault();},{passive:false});
 }
 reset(){this.mx=this.mz=0;this.fire=false;this.pointer=this.lookPointer=null;for(const k of Object.keys(this.drive))this.drive[k]=0;document.querySelectorAll('#vehicle-controls .held').forEach(b=>b.classList.remove('held'));const k=document.getElementById('stick-knob');if(k)k.style.transform='';document.getElementById('touch-fire')?.classList.remove('held');}
 setVisible(value){document.getElementById('touch-controls').hidden=!value||!this.enabled||this.vehicleMode;if(!value)document.getElementById('kit-tray').hidden=true;}
 setVehicleMode(value,visible=true){if(this.vehicleMode!==value){this.reset();this.vehicleMode=value;}document.getElementById('vehicle-controls').hidden=!value||!visible;if(value){document.getElementById('touch-controls').hidden=true;document.getElementById('kit-tray').hidden=true;}}
}
